<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { allPermissions, demoAddUser, demoChangeRole, demoUpdateUser, demoUsers } from '../services/demoAuth'
import { useAuth } from '../stores/auth'
import type { User } from '../types'
const { state } = useAuth(); const users = ref<User[]>([]); const roles = ['administrador', 'tecnico']; const canManage = computed(() => state.user?.permissions.includes('users:manage')); const createDialog = ref(false); const editDialog = ref(false); const error = ref(''); const form = ref({ id: 0, name: '', email: '', password: '', role: 'tecnico', permissions: [] as string[] })
function load() { users.value = demoUsers() }
function updateRole(user: User, role: string) { demoChangeRole(user.id, role); load() }
function openCreate() { error.value = ''; form.value = { id: 0, name: '', email: '', password: '', role: 'tecnico', permissions: ['workorders:read', 'workorders:write'] }; createDialog.value = true }
function openEdit(user: User) { error.value = ''; form.value = { id: user.id, name: user.name, email: user.email, password: '', role: user.roles[0], permissions: [...user.permissions] }; editDialog.value = true }
async function createUser() { try { if (form.value.name.length < 2 || form.value.password.length < 10) throw new Error('Nombre y contraseña de al menos 10 caracteres son obligatorios.'); await demoAddUser(form.value.name, form.value.email, form.value.password, form.value.role); createDialog.value = false; load() } catch (e: any) { error.value = e.message } }
function saveUser() { try { if (form.value.name.length < 2 || !/.+@.+\..+/.test(form.value.email)) throw new Error('Escribe un nombre y correo válidos.'); demoUpdateUser(form.value.id, form.value.name, form.value.email, form.value.role, form.value.permissions); editDialog.value = false; load() } catch (e: any) { error.value = e.message } }
onMounted(load)
</script>
<template><v-container class="py-8 dashboard"><div class="d-flex align-center justify-space-between flex-wrap ga-4 mb-7"><div><p class="eyebrow mb-1">PANEL DE CONTROL</p><h1>Hola, {{ state.user?.name }}</h1><p class="text-medium-emphasis mt-1">Gestiona el acceso de tu equipo de forma segura.</p></div><v-btn v-if="canManage" color="primary" prepend-icon="mdi-account-plus" rounded="lg" @click="openCreate">Añadir usuario</v-btn></div><v-row class="mb-2"><v-col cols="12" md="4"><v-card class="metric-card pa-5" elevation="0"><v-icon color="primary" size="32">mdi-account-group</v-icon><div class="text-h4 font-weight-bold mt-3">{{ users.length }}</div><div class="text-medium-emphasis">Usuarios registrados</div></v-card></v-col><v-col cols="12" md="4"><v-card class="metric-card pa-5" elevation="0"><v-icon color="primary" size="32">mdi-account-key</v-icon><div class="text-h4 font-weight-bold mt-3">{{ state.user?.roles.join(', ') }}</div><div class="text-medium-emphasis">Tu rol actual</div></v-card></v-col><v-col cols="12" md="4"><v-card class="metric-card pa-5" elevation="0"><v-icon color="primary" size="32">mdi-key-variant</v-icon><div class="text-h4 font-weight-bold mt-3">{{ state.user?.permissions.length }}</div><div class="text-medium-emphasis">Permisos activos</div></v-card></v-col></v-row><v-card class="mt-5 pa-2" elevation="0"><v-card-title>Usuarios, roles y permisos</v-card-title><v-table><thead><tr><th>Usuario</th><th>Correo</th><th>Rol</th><th>Permisos</th><th></th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td class="font-weight-medium">{{ user.name }}</td><td>{{ user.email }}</td><td><v-chip color="primary" size="small">{{ user.roles[0] }}</v-chip></td><td><v-chip v-for="permission in user.permissions" :key="permission" size="x-small" color="primary" variant="tonal" class="mr-1">{{ permission }}</v-chip></td><td><v-btn v-if="canManage" icon="mdi-pencil" variant="text" color="primary" @click="openEdit(user)" /></td></tr></tbody></v-table></v-card><v-dialog v-model="createDialog" max-width="520"><v-card class="pa-5"><v-card-title>Añadir usuario</v-card-title><v-alert v-if="error" type="error" density="compact">{{ error }}</v-alert><v-text-field v-model="form.name" label="Nombre" variant="outlined" class="mt-4" /><v-text-field v-model="form.email" label="Correo" variant="outlined" /><v-text-field v-model="form.password" label="Contraseña temporal" type="password" variant="outlined" hint="Mínimo 10 caracteres" persistent-hint /><v-select v-model="form.role" :items="roles" label="Rol" variant="outlined" class="mt-4" /><v-card-actions><v-spacer /><v-btn @click="createDialog = false">Cancelar</v-btn><v-btn color="primary" @click="createUser">Crear usuario</v-btn></v-card-actions></v-card></v-dialog><v-dialog v-model="editDialog" max-width="560"><v-card class="pa-5"><v-card-title>Editar usuario y permisos</v-card-title><v-alert v-if="error" type="error" density="compact">{{ error }}</v-alert><v-text-field v-model="form.name" label="Nombre" variant="outlined" class="mt-4" /><v-text-field v-model="form.email" label="Correo" variant="outlined" /><v-select v-model="form.role" :items="roles" label="Rol" variant="outlined" /><div class="text-subtitle-2 mb-2">Permisos individuales</div><v-checkbox v-for="permission in allPermissions" :key="permission" v-model="form.permissions" :label="permission" :value="permission" density="compact" hide-details /><v-card-actions><v-spacer /><v-btn @click="editDialog = false">Cancelar</v-btn><v-btn color="primary" @click="saveUser">Guardar cambios</v-btn></v-card-actions></v-card></v-dialog></v-container></template>
<style scoped>.dashboard { background: #f7faff; min-height: calc(100vh - 64px); }.eyebrow { color: #0b5fa5; font-size: .72rem; font-weight: 800; letter-spacing: 1.4px; }.dashboard h1 { color: #092f59; font-weight: 800; }.metric-card { border: 1px solid #dceafa; border-radius: 16px; }</style>
